def max_sum_rectangular_grid(grid, n):
    # Initialize the first column
    dp = grid[0]
    # Loop through the rest of the columns
    for i in range(1, n):
        # Update the current column with the maximum sum
        dp = [max(dp[j-1], dp[j]) + grid[j][i] for j in range(n)]
    # Return the maximum sum of the last column
    return max(dp)

