def max_sum_rectangular_grid(grid, n):
    if n == 0:
        return 0
    if n == 1:
        return max(grid[0][0], grid[1][0])

    prev_max = max(grid[0][0], grid[1][0])
    curr_max = max(prev_max, grid[0][1] + grid[1][1])

    for i in range(2, n):
        prev_max, curr_max = curr_max, max(curr_max, prev_max + grid[0][i] + grid[1][i])

    return curr_max

