    return 'None'  # If no repeated word is found

def max_sub_array_sum(arr, n):
    max_sum = float('-inf')
    current_sum = 0

    for i in range(n):
        current_sum += arr[i]
        if current_sum > max_sum:
            max_sum = current_sum
        if current_sum < 0:
            current_sum = 0

    return max_sum

def is_Sub_Array(arr1, arr2, len1, len2):
    i = 0
    j = 0
    while i < len1 and j < len2:
        if arr1[i] == arr2[j]:
            i += 1
            j += 1
        else:
            i += 1
    return j == len2

def big_diff(nums):
    if not nums:
        return 0
    return max(nums) - min(nums)

def perfect_squares(start, end):
    perfect_squares_list = []
    for num in range(start, end+1):
        if int(num**0.5)**2 == num:
            perfect_squares_list.append(num)
    return perfect_squares_list

def prime_num(n):
    if n <= 1:
        return False
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            return False
    return True

import re

def find_literals(text, pattern):
    match = re.search(pattern, text)
    if match:
        return (pattern, match.start(), match.end())
    else:
        return None

def max_occurrences(lst):
    counts = {}
    for item in lst:
        if item in counts:
            counts[item] += 1
        else:
            counts[item] = 1
    max_count = 0
    max_item = None
    for item, count in counts.items():
        if count > max_count:
            max_count = count
            max_item = item
    return max_item

def max_of_three(a, b, c):
    if a > b and a > c:
        return a
    elif b > a and b > c:
        return b
    else:
        return c

def equilibrium_index(arr):
    left_sum = 0
    right_sum = sum(arr)
    for i in range(len(arr)):
        right_sum -= arr[i]
        if left_sum == right_sum:
            return i
        left_sum += arr[i]
    return -1

def check_Odd_Parity(n):
    count = 0
    while n:
        count += n % 2
        n //= 2
    return count % 2 == 1

def max_run_uppercase(string):
    max_count = 0
    current_count = 0
    for char in string:
        if char.isupper():
            current_count += 1
            max_count = max(max_count, current_count)
        else:
            current_count = 0
    return max_count

def check_substring(string, substring):
    if string.startswith(substring):
        return "string starts with the given substring"
    else:
        return "string doesnt start with the given substring"

def count_alpha_dig_spl(input_string):
    alphabets = 0
    digits = 0
    special_characters = 0

    for char in input_string:
        if char.isalpha():
            alphabets += 1
        elif char.isdigit():
            digits += 1
        else:
            special_characters += 1

    return alphabets, digits, special_characters

def length_Of_Last_Word(s):
    words = s.split()
    if words:
        return len(words[-1])
    else:
        return 0

def are_Rotations(s1, s2):
    if len(s1) != len(s2):
        return False
    return s2 in (s1 + s1)

def check_subset(nested_list, subset):
    def flatten(lst):
        for item in lst:
            if isinstance(item, list):
                yield from flatten(item)
            else:
                yield item

    subset_flat = set(flatten(subset))
    nested_list_flat = set(flatten(nested_list))

    return subset_flat.issubset(nested_list_flat)

def max_sum_subseq(arr):
    n = len(arr)
    if n == 0:
        return 0
    elif n == 1:
        return arr[0]

    incl = arr[0]
    excl = 0

    for i in range(1, n):
        new_excl = max(incl, excl)
        incl = excl + arr[i]
        excl = new_excl

    return max(incl, excl)

def candidate(operations):
    balance = 0
    for op in operations:
        balance += op
        if balance < 0:
            return True
    return False

def candidate(original, substring):
    count = 0
    index = 0
    while index < len(original):
        index = original.find(substring, index)
        if index == -1:
            break
        count += 1
        index += 1
    return count

def candidate(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def candidate(n):
    if n <= 1:
        return n
    else:
        return candidate(n - 1) + candidate(n - 2)
